node -e 'const fs=require("fs"),path=require("path"),crypto=require("crypto");
const root="/root/autodl-tmp/symbolic_dynamics",base="docs/papers211_215_sequence/qa/p211_round1_preparation";
const read=p=>fs.readFileSync(path.join(root,p)),json=p=>JSON.parse(read(p).toString("utf8"));
const hash=b=>crypto.createHash("sha256").update(b).digest("hex");
function need(x,s){if(!x)throw Error(s);}
function canonical(x){if(Array.isArray(x))return x.map(canonical);if(x&&typeof x==="object")return Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonical(x[k])]));return x;}
function pins(p){return read(p).toString("utf8").trimEnd().split("\n").map(l=>{const m=l.match(/^([0-9a-f]{64})  (.+)$/);need(m,"pin syntax");return {sha256:m[1],path:m[2]};});}
const seal=pins(base+"/SHA256SUMS"),inputs=pins(base+"/INPUTS.sha256");
const actual=fs.readdirSync(path.join(root,base)).sort();need(actual.length===6&&seal.length===5,"five-payload exact inventory");
need(JSON.stringify(actual.filter(n=>n!=="SHA256SUMS"))===JSON.stringify(seal.map(r=>r.path).sort()),"manifest universe");
for(const n of actual)need(fs.lstatSync(path.join(root,base,n)).isFile()&&!fs.lstatSync(path.join(root,base,n)).isSymbolicLink(),"ordinary preparation file");
const d=json(base+"/ROLE_SELECTION_DRAFT.json"),b=json(d.author_role.accepted_pin_ledger);
const result=json("docs/papers211_215_sequence/qa/p211_round0_execution01/RESULT.json");
const rows=d.author_role.payloads,m=Object.fromEntries(rows.map(r=>[r.relative_name,r.pin]));
need(rows.length===32&&Object.keys(m).length===32&&Object.keys(b).length===32,"author rows");
need(JSON.stringify(canonical(m))===JSON.stringify(canonical(b)),"exact author metadata");
need(hash(read(d.author_role.accepted_pin_ledger))===d.author_role.accepted_pin_ledger_sha256,"ledger digest");
const metadata_bytes=rows.reduce((a,r)=>a+r.pin.bytes,0);need(metadata_bytes===1819014&&metadata_bytes===result.payload_bytes,"metadata byte sum");
const frozen_manifest=d.author_role.accepted_round0_manifest;
need(frozen_manifest.bytes===result.manifest.bytes&&frozen_manifest.sha256===result.manifest.sha256&&frozen_manifest.physical_payload_in_round1===false,"external historical manifest metadata");
const source=read("docs/papers211_215_sequence/qa/p211_round0_execution01/freeze.py").toString("utf8");
const literal=source.match(/NAMES = '\'''\'''\''([\s\S]*?)'\'''\'''\''\.split\(\)/);need(literal,"literal recorder NAMES extraction");
need(JSON.stringify(literal[1].trim().split(/\s+/).sort())===JSON.stringify(Object.keys(m).sort()),"accepted recorder literal names");
need(source.includes("PAPER.rglob('\''*'\'')")&&source.includes("current_names == set(NAMES)"),"old whole-tree equality source");
need(d.status==="PLAN_ONLY_NOT_EXECUTABLE_NOT_BOUND"&&d.binding.enabled===false,"disabled draft");
need(Object.entries(d.binding).every(([k,v])=>k==="enabled"?v===false:v===null),"all execution binding missing");
for(const k of ["scientific_executions","freeze_executions","physical_copies","canonical_adoptions"])need(d[k]===0,"zero declared actions");
const a=d.review_a_role;
for(const k of ["manifest","manifest_payload_count","all_file_count","exact_members","accepted_delta","same_a_acceptance","root_reception","initial_execution_and_full_output_acceptance","canonical_adoption","strict_pair_and_native_comparisons","complete_external_dependencies","embedded_historical_origin_mappings"])need(a[k]===null,"unknown A "+k);
const required=["REPORT.md","verify.py","parameters.json","CANONICAL.json","REPLAY_LOG.md","SOURCE_AND_PROOF.md","BUILD_REPORT.md","INPUT_PINS.sha256","FINDINGS.json","DELTA.md"];
need(JSON.stringify([...a.required_payload_names].sort())===JSON.stringify([...required].sort()),"ten minimum roles");
need(a.destination_prefix==="review_a"&&a.preserve_all_additional_evidence_and_failed_initial_material===true,"whole A role");
need(d.outer_manifest.when_A_manifest_has_N_payloads.round1_payload_count==="33 + N"&&d.outer_manifest.when_A_manifest_has_N_payloads.round1_total_file_count==="34 + N"&&d.outer_manifest.when_A_manifest_has_N_payloads.b_required_round1_input_count==="34 + N","symbolic counts");
const native=json(base+"/NATIVE_READS.json"),checks=json(base+"/CHECKS_NATIVE.json");
need(native.records.length===12&&checks.records.length===3,"original preparation record census");
need(native.records[10].result.exit_code===2&&native.records[10].result.output.includes("No such file or directory"),"old new-directory observation preserved");
const stable_indices=[1,2,3,6,7,8,9,11],stable=[];
for(const i of stable_indices){const r=native.records[i],s=r.cmd.match(/^sed -n '\''1,(\d+)p'\'' ([A-Za-z0-9_./-]+)$/);need(s,"stable read command shape");need(inputs.some(p=>p.path===s[2]),"stable read is one of ten infrastructure inputs");const raw=read(s[2]);need(r.result.exit_code===0,"old read exit");need(Buffer.from(r.result.output,"utf8").equals(raw),"archived decoded read equals complete current infrastructure file "+s[2]);stable.push({record_index:i,path:s[2],bytes:raw.length,sha256:hash(raw),complete_current_file_equals_archived_decoded_utf8:true});}
const linkTargets=new Set();for(const match of read(base+"/PLAN.md").toString("utf8").matchAll(/\]\(([^)]+)\)/g)){const t=path.resolve(root,base,match[1]);need(fs.statSync(t).isFile(),"plan local link");linkTargets.add(t);}
need(checks.records.every(r=>r.result.exit_code===0),"archived metadata checks exit");
const prepRows=actual.map(n=>({path:base+"/"+n,bytes:read(base+"/"+n).length,sha256:hash(read(base+"/"+n))}));
const inputRows=inputs.map(r=>({path:r.path,bytes:read(r.path).length,sha256:hash(read(r.path))}));
need(inputs.length===10&&inputs.every((r,i)=>r.sha256===inputRows[i].sha256),"ten current input hashes");
need(seal.every(r=>r.sha256===hash(read(base+"/"+r.path))),"five current payload hashes");
process.stdout.write(JSON.stringify({status:"STATIC_METADATA_COMPATIBLE_NO_FUTURE_ACCEPTANCE",preparation_payloads:5,preparation_total_files:6,preparation_manifest_sha256:hash(read(base+"/SHA256SUMS")),stable_inputs:10,author_metadata_rows:32,author_metadata_bytes:metadata_bytes,author_ledger_sha256:d.author_role.accepted_pin_ledger_sha256,accepted_round0_manifest_metadata_matches:true,recorded_round0_execution_status:result.status,A_required_minimum_roles:10,A_exact_members_and_acceptance:null,binding_enabled:false,counts:d.outer_manifest.when_A_manifest_has_N_payloads,old_recursive_inventory_requires_scoped_adaptation:true,native_read_records:12,native_check_records:3,archived_complete_stable_read_comparisons:stable,current_plan_unique_file_links:linkTargets.size,native_provenance_limit:"Original preparation archives contain cmd/result tool records, not native argv/cwd/env and separated process streams; navigation records are historical observations.",paper_payload_bodies_opened:0,A_tree_accesses:0,adapter_or_saved_checker_invocations:0,physical_copies:0,scientific_executions:0,input_rows:[...prepRows,...inputRows]},null,2)+"\n");
'

